contracts=[{'schema':'ghc.model.contract.v2','model':m,'quantities':dict(zip(['x','y','value'],q)),'units':dict(zip(['x','y','value'],u)),'time':{'quantity':'simulation step','unit':'step index','physical_seconds_claim':False},'assumptions':a,'expected_baseline':b,'tolerance':t,'falsifier':f,'supersedes':'docs/avelin-reed/v707-v6-r2/model-definitions.json#'+m,'evidence':'synthetic; no independent reproduction or empirical confirmation'} for m,q,u,a,b,t,f in rows]
