 r.update({'schema':'ghc.lab.source-summary.v1','inputs':{'kind':'source_artifact_references','paths':[a['path'] for a in r['artifacts']]},'result':{'kind':'historical_overview_summary','original_individual_result_status':'not_imported_by_this_summary'},'checks':['committed artifact located','raw selected artifact digest recorded'],'limitations':['A source catalogue entry does not independently reproduce its results.','See the exact source for original outcomes and gaps.'],'superseded_record_links':[]})
